import { describe, expect, it } from "vitest";
import { parseAmount } from "@/lib/money";

describe("parseAmount", () => {
  it("parses plain amounts", () => {
    expect(parseAmount("450.00")).toBe(450);
  });

  it("handles thousands separators and a dollar sign", () => {
    expect(parseAmount("2,300.00")).toBe(2300);
    expect(parseAmount(" $1,250,000.00 ")).toBe(1250000);
  });
});
EOF
cat > lib/csv.test.ts <<'EOF'
import { describe, expect, it } from "vitest";
import { importCsv } from "@/lib/csv";

describe("importCsv", () => {
  it("parses quoted amounts with thousands separators", () => {
    const [row] = importCsv('customer,amount,dueDate\nAcme,"1,200.00",2026-12-01', "alice");
    expect(row.amount).toBe("1200.00");
  });

  it("rejects invalid amounts", () => {
    expect(() => importCsv("customer,amount,dueDate\nAcme,abc,2026-12-01", "alice")).toThrow(/Row 2/);
  });
});
EOF
